import { Scene, MarkupText, Write, VBox, CameraModel, Rate, hex } from 'retiam';

export default class ShowcaseScene extends Scene {
    public async run() {
        this.camera.model = CameraModel.ORTHOGRAPHIC;

        const title = new MarkupText("Kinetic Energy", { fontSize: 1.0, fill: hex("#38BDF8") });
        const body = new MarkupText("The energy is given by $E_k = \\frac{1}{2}mv^2$.", { fontSize: 0.65 });

        // 1. Spatial arrangement without container coupling
        VBox.arrange({ gap: 0.8, align: 'center', center: [0, 0.5, 0] }, title, body);

        // 2. Camera framing with array of entities
        this.camera.frame([title, body], { padding: 0.25 });

        // 3. Independent sequential playback (body does NOT appear until Write(body))
        await this.play(new Write(title, { duration: 1200 }));
        await this.wait(400);
        await this.play(new Write(body, { duration: 2000 }));
    }
}

